import{_ as n,a0 as l,w as r,s as p,I as t,x as o,a1 as i,A as s,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"命令列快速提示：權限進階 | LCTT x X-CMD","titleTemplate":false,"description":"命令列快速提示：權限進階 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令列快速提示：權限進階 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令列快速提示：權限進階 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190729 Command line quick tips- More about permissions","title":"命令列快速提示：權限進階","tag":"201908","desc":""},"relativePath":"201908/20190729 Command line quick tips- More about permissions.md","filePath":"[post].md"}'),c={name:"201908/20190729 Command line quick tips- More about permissions.md"};function u(g,e,m,f,h,k){const d=l("Link");return r(),p("div",null,[e[23]||(e[23]=t("h1",{id:"命令列快速提示-權限進階",tabindex:"-1"},[o("命令列快速提示：權限進階 "),t("a",{class:"header-anchor",href:"#命令列快速提示-權限進階","aria-label":"Permalink to “命令列快速提示：權限進階”"},"​")],-1)),e[24]||(e[24]=t("p",null,[t("img",{src:"https://fedoramagazine.org/wp-content/uploads/2018/10/commandlinequicktips-816x345.jpg",alt:""})],-1)),t("p",null,[e[2]||(e[2]=o("前一篇文章",-1)),i(d,{href:"https://linux.cn/article-11123-1.html"},{default:s(()=>[...e[0]||(e[0]=[o("介紹了 Fedora 系統上有關文件權限的一些基礎知識",-1)])]),_:1}),e[3]||(e[3]=o("。本部分介紹使用權限管理文件訪問和共享的其他方法。它建立在前一篇文章中的知識和示例的基礎上，所以如果你還沒有閲讀過那篇文章，請",-1)),i(d,{href:"https://linux.cn/article-11123-1.html"},{default:s(()=>[...e[1]||(e[1]=[o("查看",-1)])]),_:1}),e[4]||(e[4]=o("它。",-1))]),e[25]||(e[25]=a('<h3 id="符號與八進制" tabindex="-1">符號與八進制 <a class="header-anchor" href="#符號與八進制" aria-label="Permalink to “符號與八進制”">​</a></h3><p>在上一篇文章中，你瞭解到文件有三個不同的權限集。擁有該文件的用户有一個集合，擁有該文件的組的成員有一個集合，然後最終一個集合適用於其他所有人。在長列表（<code>ls -l</code>）中這些權限使用符號模式顯示在屏幕上。</p><p>每個集合都有 <code>r</code>、<code>w</code> 和 <code>x</code> 條目，表示特定用户（所有者、組成員或其他）是否可以讀取、寫入或執行該文件。但是還有另一種表達這些權限的方法：八進制模式。</p>',3)),t("p",null,[e[6]||(e[6]=o("你已經習慣了",-1)),i(d,{href:"https://en.wikipedia.org/wiki/Decimal"},{default:s(()=>[...e[5]||(e[5]=[o("十進制",-1)])]),_:1}),e[7]||(e[7]=a("編號系統，它有十個不同的值（<code>0</code> 到 <code>9</code>）。另一方面，八進制系統有八個不同的值（<code>0</code> 到 <code>7</code>）。在表示權限時，八進制用作速記來顯示 <code>r</code>、<code>w</code> 和 <code>x</code> 字段的值。將每個字段視為具有如下值：",15))]),e[26]||(e[26]=a(`<ul><li><code>r</code> = 4</li><li><code>w</code> = 2</li><li><code>x</code> = 1</li></ul><p>現在，你可以使用單個八進制值表達任何組合。例如，讀取和寫入權限（但沒有執行權限）的值為 <code>6</code>。讀取和執行權限的值僅為 <code>5</code>。文件的 <code>rwxr-xr-x</code> 符號權限的八進制值為 <code>755</code>。</p><p>與符號值類似，你可以使用八進制值使用 <code>chmod</code> 命令設置文件權限。以下兩個命令對文件設置相同的權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>chmod u=rw,g=r,o=r myfile1</span></span>
<span class="line"><span>chmod 644 myfile1</span></span></code></pre></div><h3 id="特殊權限位" tabindex="-1">特殊權限位 <a class="header-anchor" href="#特殊權限位" aria-label="Permalink to “特殊權限位”">​</a></h3><p>文件上還有幾個特殊權限位。這些被稱為 <code>setuid</code>（或 <code>suid</code>）、<code>setgid</code>（或 <code>sgid</code>），以及<ruby>粘滯位<rt>sticky bit</rt></ruby>（或<ruby>阻止刪除位<rt>delete inhibit</rt></ruby>）。 將此視為另一組八進制值：</p><ul><li><code>setuid</code> = 4</li><li><code>setgid</code> = 2</li><li><code>sticky</code> = 1</li></ul><p><strong>除非</strong>該文件是可執行的，否則 <code>setuid</code> 位是被忽略的。如果是可執行的這種情況，則該文件（可能是應用程序或腳本）的運行就像擁有該文件的用户啓動的一樣。<code>setuid</code> 的一個很好的例子是 <code>/bin/passwd</code> 實用程序，它允許用户設置或更改密碼。此實用程序必須能夠寫入到不允許普通用户更改的文件中（LCTT 譯註：此處是指 <code>/etc/passwd</code> 和 <code>/etc/shadow</code>）。因此它需要精心編寫，由 <code>root</code> 用户擁有，並具有 <code>setuid</code> 位，以便它可以更改密碼相關文件。</p><p><code>setgid</code> 位對於可執行文件的工作方式類似。該文件將使用擁有它的組的權限運行。但是，<code>setgid</code> 對於目錄還有一個額外的用途。如果在具有 <code>setgid</code> 權限的目錄中創建文件，則該文件的組所有者將設置為該目錄的組所有者。</p><p>最後，雖然文件粘滯位沒有意義會被忽略，但它對目錄很有用。在目錄上設置的粘滯位將阻止用户刪除其他用户擁有的該目錄中的文件。</p><p>在八進制模式下使用 <code>chmod</code> 設置這些位的方法是添加一個值前綴，例如 <code>4755</code>，可以將 <code>setuid</code> 添加到可執行文件中。在符號模式下，<code>u</code> 和 <code>g</code> 也可用於設置或刪除 <code>setuid</code> 和 <code>setgid</code>，例如 <code>u+s,g+s</code>。粘滯位使用 <code>o+t</code> 設置。（其他的組合，如 <code>o+s</code> 或 <code>u+t</code>，是沒有意義的，會被忽略。）</p><h3 id="共享與特殊權限" tabindex="-1">共享與特殊權限 <a class="header-anchor" href="#共享與特殊權限" aria-label="Permalink to “共享與特殊權限”">​</a></h3><p>回想一下前一篇文章中關於需要共享文件的財務團隊的示例。可以想像，特殊權限位有助於更有效地解決問題。原來的解決方案只是創建了一個整個組可以寫入的目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>drwxrwx---. 2 root finance 4096 Jul  6 15:35 finance</span></span></code></pre></div><p>此目錄的一個問題是，<code>finance</code> 組成員的用户 <code>dwayne</code> 和 <code>jill</code> 可以刪除彼此的文件。這對於共享空間來説不是最佳選擇。它在某些情況下可能有用，但在處理財務記錄時可能不會！</p><p>另一個問題是此目錄中的文件可能無法真正共享，因為它們將由 <code>dwayne</code> 和 <code>jill</code> 的默認組擁有 - 很可能用户私有組也命名為 <code>dwayne</code> 和 <code>jill</code>，而不是 <code>finance</code>。</p><p>解決此問題的更好方法是在文件夾上設置 <code>setgid</code> 和粘滯位。這將做兩件事：使文件夾中創建的文件自動歸 <code>finance</code> 組所有，並防止 <code>dwayne</code> 和 <code>jill</code> 刪除彼此的文件。下面這些命令中的任何一個都可以工作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo chmod 3770 finance</span></span>
<span class="line"><span>sudo chmod u+rwx,g+rwxs,o+t finance</span></span></code></pre></div><p>該文件的長列表現在顯示了所應用的新特殊權限。粘滯位顯示為 <code>T</code> 而不是 <code>t</code>，因為 <code>finance</code> 組之外的用户無法搜索該文件夾。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>drwxrws--T. 2 root finance 4096 Jul  6 15:35 finance</span></span></code></pre></div><hr>`,21)),t("p",null,[e[9]||(e[9]=o("via: ",-1)),i(d,{href:"https://fedoramagazine.org/command-line-quick-tips-more-about-permissions/"},{default:s(()=>[...e[8]||(e[8]=[o("https://fedoramagazine.org/command-line-quick-tips-more-about-permissions/",-1)])]),_:1})]),t("p",null,[e[14]||(e[14]=o("作者：",-1)),i(d,{href:"https://fedoramagazine.org/author/pfrields/"},{default:s(()=>[...e[10]||(e[10]=[o("Paul W. Frields",-1)])]),_:1}),e[15]||(e[15]=o(" 選題：",-1)),i(d,{href:"https://github.com/lujun9972"},{default:s(()=>[...e[11]||(e[11]=[o("lujun9972",-1)])]),_:1}),e[16]||(e[16]=o(" 譯者：",-1)),i(d,{href:"https://github.com/wxy"},{default:s(()=>[...e[12]||(e[12]=[o("wxy",-1)])]),_:1}),e[17]||(e[17]=o(" 校對：",-1)),i(d,{href:"https://github.com/wxy"},{default:s(()=>[...e[13]||(e[13]=[o("wxy",-1)])]),_:1})]),t("p",null,[e[20]||(e[20]=o("本文由 ",-1)),i(d,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[18]||(e[18]=[o("LCTT",-1)])]),_:1}),e[21]||(e[21]=o(" 原創編譯，",-1)),i(d,{href:"https://linux.cn/"},{default:s(()=>[...e[19]||(e[19]=[o("Linux中國",-1)])]),_:1}),e[22]||(e[22]=o(" 榮譽推出",-1))])])}const C=n(c,[["render",u]]);export{x as __pageData,C as default};
